  const origin = typeof issueRecord.origin === "string" ? issueRecord.origin : undefined;

  switch (code) {
    case "invalid_type":
      if (issueRecord.input === undefined) {
        return "不能为空。";
      }
      if (issueRecord.expected === "string") {
        return "必须是文本。";
      }
      if (issueRecord.expected === "number") {
