      throw new Error("基础角色不存在");
    }
    const latest = await prisma.baseCharacterRevision.findFirst({
      where: { baseCharacterId },
      orderBy: { version: "desc" },
    });
    return prisma.baseCharacterRevision.create({
      data: {
        baseCharacterId,
        version: (latest?.version ?? 0) + 1,
