    });
    if (!timelineFinalization.checkpointWritten) {
      throw new Error("Chapter timeline finalization is still running");
    }
    await this.markChapterStatus(input.chapterId, needsRepair ? "needs_repair" : "pending_review");
    if (!needsRepair) {
