      issues.push({
        ledgerKey: item.ledgerKey,
        code: signal.code,
        severity: signal.severity,
        description: `伏笔“${item.title}”存在专项风险：${signal.summary}`,
        evidence: item.evidence[0]?.summary || item.summary,
