        sceneType: input.sceneType ?? "interior",
        bible: input.bible ? JSON.stringify(input.bible) : null,
        sortOrder: input.sortOrder ?? 0,
        sheetData: JSON.stringify({ status: "idle" } satisfies SceneSheetData),
      },
