    }
    if (/(公司|企业|部门|机构|社群|圈层|家庭共同体|社区组织|中介机构|机关|生活社群|兴趣联盟|地缘势力)/.test(raw)) {
      return "organization";
    }
    if (/(临时联盟|人物|角色|情感|关系线)/.test(raw)) {
      return "other";
    }
  }
  return inferFactionNodeType(label);
}

